package io.github.r3neer.scalebrews.client.collision.preparation;
import java.util.*;import java.lang.reflect.*;import java.nio.file.*;
import org.joml.*;import com.google.gson.*;
import net.fabricmc.fabric.api.client.gametest.v1.*;import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.client.model.*;import net.minecraft.client.model.geom.*;import net.minecraft.client.model.animal.turtle.*;import net.minecraft.client.renderer.entity.state.*;
import io.github.r3neer.scalebrews.client.mixin.ModelPartAccess;import io.github.r3neer.scalebrews.collision.api.spi.PoseEngine;import io.github.r3neer.scalebrews.collision.pose.NumericPoseProgram;import io.github.r3neer.scalebrews.collision.geometry.*;
public final class S59AdversarialFiniteProof implements FabricClientGameTest {
 static void check(boolean b,String reason){if(!b)throw new AssertionError("S59 ADV "+reason);}
 @SuppressWarnings({"unchecked","rawtypes"}) public void runTest(ClientGameTestContext context){
  try{OriginalFinitePosePreparation.inspect(null);throw new AssertionError("S59 ADV off-thread admitted");}catch(IllegalStateException expected){}
  var world=context.worldBuilder().create();try{context.runOnClient(mc->{try{
   check(!OriginalFinitePosePreparation.inspect(null).admitted(),"null model");
   var model=new BabyTurtleModel(mc.getEntityModels().bakeLayer(ModelLayers.TURTLE_BABY));var adult=new AdultTurtleModel(mc.getEntityModels().bakeLayer(ModelLayers.TURTLE));
   String adultBefore=S55AdversarialGeometryProof.state(adult.root());check(!OriginalFinitePosePreparation.inspect(adult).admitted(),"adult visible write admitted");check(adultBefore.equals(S55AdversarialGeometryProof.state(adult.root())),"rejected adult mutated");
   var parts=S55AdversarialGeometryProof.parts(model.root());var initial=new IdentityHashMap<ModelPart,PartPose>();var current=new IdentityHashMap<ModelPart,PartPose>();var flags=new IdentityHashMap<ModelPart,boolean[]>();int partIndex=0;
   for(var p:parts.values()){initial.put(p,p.getInitialPose());current.put(p,S55AdversarialGeometryProof.current(p));flags.put(p,new boolean[]{p.visible,p.skipDraw});float n=++partIndex*.051f;p.setInitialPose(new PartPose(n,-n*.7f,n*.2f,n*.09f,-n*.13f,n*.07f,-1.05f,.95f,1.2f));p.loadPose(new PartPose(3,4,5,.7f,.3f,-.2f,2,3,4));p.visible=false;p.skipDraw=true;}
   var fields=S58AdversarialCompoundProof.partFields(model);var alias=fields.stream().filter(f->f.getName().equals("leftFrontLeg")).findFirst().orElseThrow();var target=fields.stream().filter(f->f.getName().equals("rightHindLeg")).findFirst().orElseThrow();Object oldAlias=alias.get(model);int matrices=0,cubes=0,samples=0;boolean aliasChanges=false;var ordinary=new HashMap<String,Map<String,Matrix4f>>();var reports=new ArrayList<Object>();var tables=new ArrayList<Object>();
   try{for(int variant=0;variant<2;variant++){
    if(variant==1)alias.set(model,target.get(model));String before=S55AdversarialGeometryProof.state(model.root());var relations=new ArrayList<Object>();for(var f:fields)relations.add(f.get(model));
    var result=OriginalFinitePosePreparation.inspect(model);check(result.admitted(),"finite original rejected "+result.absence());var table=result.prepared();check(before.equals(S55AdversarialGeometryProof.state(model.root())),"prepare changed nine fields/flags/initial/tree");for(int i=0;i<fields.size();i++)check(fields.get(i).get(model)==relations.get(i),"prepare changed field identity");
    check(!OriginalLinearPosePreparation.inspect(model).admitted(),"linear strict branch veto lost");check(!OriginalResetPosePreparation.inspect(model).admitted(),"reset strict veto lost");check(table.equals(OriginalFinitePosePreparation.inspect(model).prepared()),"repeat finite digest drift");
    check(table.booleanInputs().size()==2&&table.rows().size()==4,"complete discovered boolean assignment set");check(table.verifiedInstructions()>0&&table.verifiedInstructions()<=1048576,"global work bounds");var predicateSets=new HashSet<Map<String,Boolean>>();for(var row:table.rows())check(predicateSets.add(row.predicate())&&row.predicate().size()==table.booleanInputs().size(),"duplicate/partial predicate");
    Object sameGeometry=table.rows().getFirst().numeric().program().geometry();for(var row:table.rows())check(row.numeric().program().geometry()==sameGeometry,"geometry not shared");tables.add(table);
    for(int rowIndex=0;rowIndex<table.rows().size();rowIndex++){
     var row=table.rows().get(rowIndex);var numeric=row.numeric();var program=new Gson().fromJson(new Gson().toJson(numeric.program()),NumericPoseProgram.class);check(program.equals(numeric.program()),"neutral DTO roundtrip");var bound=program.bind(program.geometry()).orElseThrow();var observations=new ArrayList<Object>();var state=new TurtleRenderState();
     for(var source:table.booleanInputs()){Field f=Class.forName(source.owner()).getDeclaredField(source.name());f.setAccessible(true);f.setBoolean(state,row.predicate().get(source.channel()));}
     for(int tick=0;tick<5;tick++){
      state.hasEgg=(tick&1)!=0;var channels=new TreeMap<String,Float>();int i=0;for(var source:numeric.inputs()){float v=(tick-2)*1.234567f*(++i+.37f);Field f=Class.forName(source.owner()).getDeclaredField(source.name());f.setAccessible(true);f.setFloat(state,v);channels.put(source.channel(),v);}
      check(bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,false,channels)).isEmpty(),"incompatible ordinary admitted");if(!channels.isEmpty()){var missing=new TreeMap<>(channels);missing.remove(missing.firstKey());check(bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,true,missing)).isEmpty(),"missing per-row float admitted");var invalid=new TreeMap<>(channels);invalid.put(invalid.firstKey(),Float.NaN);try{new PoseEngine.Inputs(0,0,0,0,0,true,invalid);throw new AssertionError("S59 ADV nonfinite channels admitted");}catch(IllegalArgumentException expected){}}
      String noChange=S55AdversarialGeometryProof.state(model.root());var pose=bound.evaluate(new PoseEngine.Inputs(0,0,0,0,0,true,channels)).orElseThrow();check(noChange.equals(S55AdversarialGeometryProof.state(model.root())),"common evaluation mutated shared model");var evaluated=program.geometry().transforms(pose);model.setupAnim(state);var reference=S55AdversarialGeometryProof.nativeMatrices(model.root());check(reference.keySet().equals(evaluated.keySet()),"joint membership");
      for(String id:reference.keySet()){check(reference.get(id).equals(evaluated.get(id),3e-6f),"row matrix differs "+id+" row="+rowIndex+" tick="+tick+" alias="+variant);matrices++;}
      String key=rowIndex+"/"+tick;if(variant==0){var copy=new TreeMap<String,Matrix4f>();reference.forEach((id,m)->copy.put(id,new Matrix4f(m)));ordinary.put(key,copy);}else for(String id:reference.keySet())if(!reference.get(id).equals(ordinary.get(key).get(id),3e-6f))aliasChanges=true;
      for(var piece:program.geometry().pieces()){var cube=((ModelPartAccess)(Object)parts.get(piece.part())).scalebrews$cubes().get(Integer.parseInt(piece.id().substring(piece.id().lastIndexOf("cube_")+5)));var vertices=new ArrayList<Vector3f>();for(var polygon:cube.polygons)for(var v:polygon.vertices())vertices.add(reference.get(piece.part()).transformPosition(new Vector3f(v.worldX(),v.worldY(),v.worldZ())));var box=ConvexBox.of(piece.box(),evaluated.get(piece.part()));for(var p:box.vertices())check(vertices.stream().anyMatch(v->S58AdversarialCompoundProof.cornerMatch(v,p,piece.box(),reference.get(piece.part()),evaluated.get(piece.part()))),"native corner missing "+piece.id());for(var v:vertices)check(box.vertices().stream().anyMatch(p->S58AdversarialCompoundProof.cornerMatch(v,p,piece.box(),reference.get(piece.part()),evaluated.get(piece.part()))),"native vertex lost "+piece.id());cubes++;}
      String animated=S55AdversarialGeometryProof.state(model.root());check(table.equals(OriginalFinitePosePreparation.inspect(model).prepared()),"animated recompilation changed identity");check(animated.equals(S55AdversarialGeometryProof.state(model.root())),"animated inspect changed state");observations.add(Map.of("channels",channels,"matrices",reference.entrySet().stream().collect(java.util.stream.Collectors.toMap(Map.Entry::getKey,e->ModelGeometry.values(e.getValue())))));samples++;
     }
     reports.add(Map.of("program",program,"schema",numeric.inputs(),"alias",variant,"predicate",row.predicate(),"samples",observations));
    }
   }check(aliasChanges,"alias oracle vacuous");}finally{alias.set(model,oldAlias);for(var p:parts.values()){p.setInitialPose(initial.get(p));p.loadPose(current.get(p));p.visible=flags.get(p)[0];p.skipDraw=flags.get(p)[1];}}
   var out=Path.of("s59-adversarial-snapshots");Files.createDirectories(out);var gson=new GsonBuilder().setPrettyPrinting().create();Files.writeString(out.resolve("programs.json"),gson.toJson(reports));Files.writeString(out.resolve("tables.json"),gson.toJson(tables));System.out.println("S59_INDEPENDENT_FINITE_PASS assignments=4 aliases=2 samples="+samples+" matrices="+matrices+" cubes="+cubes+" completePredicates=true strictLinear=true");
  }catch(Exception x){throw new AssertionError(x);}});}finally{world.close();}
 }
}
